class Solution:
    def maxMatchingIndices(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)
        best = 0
        for s in range(n):
            c = sum(nums1[(i + s) % n] == nums2[i] for i in range(n))
            best = max(best, c)
            if best == n:
                break
        return best

