class Solution {
public:
    int maxMatchingIndices(vector<int>& nums1, vector<int>& nums2) {
        int n = nums1.size(), best = 0;
        for (int s = 0; s < n && best < n; s++) {
            int c = 0;
            for (int i = 0; i < n; i++)
                c += nums1[(i + s) % n] == nums2[i];
            best = max(best, c);
        }
        return best;
    }
};

