class Solution:
    def maxMatchingIndices(self, nums1: List[int], nums2: List[int]) -> int:
        from collections import defaultdict
        pos = defaultdict(list)
        for j, v in enumerate(nums2):
            pos[v].append(j)
        cnt = defaultdict(int)
        n = len(nums1)
        for i, v in enumerate(nums1):
            for j in pos.get(v, ()):
                cnt[(j - i) % n] += 1
        return max(cnt.values()) if cnt else 0

