class Solution {
public:
    int maxMatchingIndices(vector<int>& nums1, vector<int>& nums2) {
        int n = nums1.size();
        unordered_map<int, vector<int>> pos;
        for (int j = 0; j < n; j++) pos[nums2[j]].push_back(j);
        unordered_map<int, int> cnt;
        int best = 0;
        for (int i = 0; i < n; i++) {
            auto it = pos.find(nums1[i]);
            if (it == pos.end()) continue;
            for (int j : it->second)
                best = max(best, ++cnt[((j - i) % n + n) % n]);
        }
        return best;
    }
};

