class Solution {
    public int maxMatchingIndices(int[] nums1, int[] nums2) {
        int n = nums1.length;
        Map<Integer, List<Integer>> pos = new HashMap<>();
        for (int j = 0; j < n; j++)
            pos.computeIfAbsent(nums2[j], x -> new ArrayList<>()).add(j);
        Map<Integer, Integer> cnt = new HashMap<>();
        int best = 0;
        for (int i = 0; i < n; i++) {
            List<Integer> js = pos.get(nums1[i]);
            if (js == null) continue;
            for (int j : js) {
                int sh = ((j - i) % n + n) % n;
                best = Math.max(best, cnt.merge(sh, 1, Integer::sum));
            }
        }
        return best;
    }
}

