var maxMatchingIndices = function(nums1, nums2) {
    const n = nums1.length;
    const pos = new Map();
    nums2.forEach((v, j) => {
        if (!pos.has(v)) pos.set(v, []);
        pos.get(v).push(j);
    });
    const cnt = new Map();
    let best = 0;
    for (let i = 0; i < n; i++) {
        for (const j of pos.get(nums1[i]) || []) {
            const sh = ((j - i) % n + n) % n;
            const c = (cnt.get(sh) || 0) + 1;
            cnt.set(sh, c);
            best = Math.max(best, c);
        }
    }
    return best;
};
